output_text:
[
  {
    "id": "entry_cart_required",
    "text": "A shopper must take the entry cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "entry_cart_pickup": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "entry_cart_pickup"
    }
  },
  {
    "id": "no_cartless_item_pickup",
    "text": "Items should not be picked up from shelves unless the shopper currently has the cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_loose_hand_carrying",
    "text": "A shopper must not move around or exit while carrying a loose item by hand.",
    "abstraction": {
      "state_properties": {
        "hand_carrying": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hand_carrying",
          {
            "or": [
              "MOVE",
              "EXIT"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "cart_return_bay_only",
    "text": "A cart may be put down only at the designated top-left return bay.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "away_from_cart_return_bay": {
          "not": "cart_return_bay"
        }
      },
      "events": {
        "cart_put_down_away_from_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_put_down_away_from_bay"
    }
  },
  {
    "id": "park_cart_when_reaching_service_bay",
    "text": "If a shopper reaches the top-left service bay while pushing a cart, they must park the cart there before exiting.",
    "abstraction": {
      "state_properties": {
        "service_bay": "at(0,1)",
        "at_service_with_cart": {
          "and": [
            "service_bay",
            "hasCart"
          ]
        }
      },
      "events": {
        "service_cart_parked": {
          "pre": {
            "and": [
              "at_service_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "cartAt(0,1)",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "at_service_with_cart",
      "discharge": "service_cart_parked"
    }
  },
  {
    "id": "resolve_service_cart_drop",
    "text": "After parking the cart at the service bay, the shopper must either reclaim it or depart the bay without the cart.",
    "abstraction": {
      "state_properties": {
        "service_bay": "at(0,1)",
        "cartless": {
          "not": "hasCart"
        },
        "service_cart_waiting": "cartAt(0,1)",
        "at_service_with_cart": {
          "and": [
            "service_bay",
            "hasCart"
          ]
        },
        "at_service_cartless_with_cart_waiting": {
          "and": [
            "service_bay",
            "cartless",
            "service_cart_waiting"
          ]
        }
      },
      "events": {
        "service_cart_parked": {
          "pre": {
            "and": [
              "at_service_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "service_cart_waiting",
              "cartless"
            ]
          }
        },
        "service_cart_reclaimed": {
          "pre": {
            "and": [
              "at_service_cartless_with_cart_waiting",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "cartless_service_departure": {
          "pre": {
            "and": [
              "at_service_cartless_with_cart_waiting",
              {
                "or": [
                  "S",
                  "E"
                ]
              }
            ]
          },
          "post": {
            "and": [
              "cartless",
              "service_cart_waiting"
            ]
          }
        },
        "service_drop_resolved": {
          "pre": {
            "or": [
              "service_cart_reclaimed",
              "cartless_service_departure"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "service_cart_parked",
      "discharge": "service_drop_resolved"
    }
  },
  {
    "id": "cart_accounted_for_at_exit",
    "text": "A shopper may exit only if the cart is either still with them or has been left at the service return bay.",
    "abstraction": {
      "state_properties": {
        "cart_with_shopper": "hasCart",
        "cart_returned_to_service_bay": "cartAt(0,1)",
        "cart_accounted_for": {
          "or": [
            "cart_with_shopper",
            "cart_returned_to_service_bay"
          ]
        },
        "cart_unaccounted_for": {
          "not": "cart_accounted_for"
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "cart_unaccounted_for"
        ]
      }
    }
  },
  {
    "id": "no_cart_in_upper_right_pedestrian_cell",
    "text": "The upper-right cell at (8,2) is a pedestrian-only shortcut and must not be entered or occupied while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "upper_right_pedestrian_cell": "at(8,2)"
      },
      "events": {
        "cart_enters_upper_right_pedestrian_cell": {
          "pre": {
            "and": [
              "pushing_cart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "pushing_cart",
              "upper_right_pedestrian_cell"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cart_enters_upper_right_pedestrian_cell",
          {
            "and": [
              "pushing_cart",
              "upper_right_pedestrian_cell",
              "MOVE"
            ]
          }
        ]
      }
    }
  }
]
